reuse={'wyrcean':'wyrcean-make','geopenian':'geopenian-open','ahebban':'ahebban-u14-raise','plegian':'plegian-u16-play','ceosan':'ceosan-1','leornian':'leornian-learn','ondraedan':'ondraedan-u13','geseon':'geseon-1','settan':'settan-1','etan':'etan-1','forgiefan':'forgiefan-u16-forgive','geliefan':'geliefan-u14-believe'}
